create table RB_CLIENT_ACCT_RELATION (BASE_ACCT_NO VARCHAR(50) not null  ,CLIENT_NO VARCHAR(22) not null  ,ACCT_SEQ_NO VARCHAR(5) not null  ,ACCT_INTERNAL_KEY INT null  ,ACCT_CCY VARCHAR(3) null  ,PROD_TYPE VARCHAR(20) null  ,DEFAULT_ACCT_FLAG VARCHAR(1) null  ,REL_STATUS VARCHAR(1) null  ,CLIENT_ACCT_TYPE VARCHAR(1) null  ,CREATE_DATE TIMESTAMP(3) null  ,UPDATE_DATE TIMESTAMP(3) null  ,CREATE_USER_ID VARCHAR(30) null  ,UPDATE_USER_ID VARCHAR(30) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  , primary key(BASE_ACCT_NO,CLIENT_NO,ACCT_SEQ_NO));